import{_ as e}from"./chunks/settings-sw.pc.en.DiHbUhNv.js";import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.BjM_ivYE.js";const g=JSON.parse('{"title":"Version rollback","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/version-rollback.md","filePath":"manual/troubleshooting/version-rollback.md","lastUpdated":1789720001000}'),l={name:"manual/troubleshooting/version-rollback.md"};function i(s,o,d,c,h,b){return a(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="version-rollback" tabindex="-1">Version rollback <a class="header-anchor" href="#version-rollback" aria-label="Permalink to &quot;Version rollback&quot;">​</a></h1><p>When a new version causes a problem and you need to go back. Rolling back uses <strong>the same screen and the same steps</strong> as updating — pick a lower version from the list; nothing prevents it.</p><h2 id="before" tabindex="-1">Before you roll back <a class="header-anchor" href="#before" aria-label="Permalink to &quot;Before you roll back {#before}&quot;">​</a></h2><ul><li>Know the <strong>version number</strong> you want to go back to.</li><li><strong>The app and the robot are separate targets.</strong> Decide which one you are rolling back.</li><li>Rolling back the robot requires a reboot, so work <strong>somewhere you can sit the robot down</strong>.</li></ul><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Robot software <strong>only takes effect after a reboot.</strong> Rebooting cuts motor power and the robot sags to the ground — <strong>sit it down first</strong>, make sure it is resting on the floor, and do not move it until the reboot finishes. While the robot is standing it ignores the reboot command and <strong>the app shows no error.</strong></p></div></div><h2 id="rollback-robot" tabindex="-1">Rolling back the robot <a class="header-anchor" href="#rollback-robot" aria-label="Permalink to &quot;Rolling back the robot {#rollback-robot}&quot;">​</a></h2><p><img src="'+e+'" alt="Robot settings → Software update"></p><ol><li>Put the controller on a <strong>Wi-Fi network with internet</strong> (not the robot&#39;s).</li><li>Open <strong>Robot settings → Software update</strong>.</li><li>Press <code>Check versions</code> to fetch the list, then <code>Download</code> on the <strong>earlier version</strong> you want. The downloaded file stays on the device.</li><li>Reconnect the controller to the <strong>robot Wi-Fi</strong> (the network starting with <code>RBQ_</code>).</li><li>Check that the <code>Update file</code> card holds that version and that <code>Target</code> is <code>Motion</code>.</li><li>Press <code>Send robot software</code>, then <code>Send</code> in the confirmation dialog.</li><li>When the transfer finishes it offers a reboot. <strong>Sit the robot down</strong>, then press <code>Reboot now</code>.</li><li>Reconnect and check that <code>Version</code> on the <code>Current robot</code> card is the version you rolled back to.</li></ol><p>Every item on that screen is described in <a href="/RBQ/manual/gui/software-update.html">Software Update</a>.</p><h2 id="rollback-app" tabindex="-1">Rolling back the app <a class="header-anchor" href="#rollback-app" aria-label="Permalink to &quot;Rolling back the app {#rollback-app}&quot;">​</a></h2><p>How you roll back depends on how the app was installed.</p><table tabindex="0"><thead><tr><th>Install route</th><th>How to roll back</th></tr></thead><tbody><tr><td><strong>Desktop · Steam Deck</strong></td><td><code>Download</code> the earlier version on the same screen, then switch to it with <code>Install app</code> on that row</td></tr><tr><td><strong>Android (APK installed directly)</strong></td><td>Get the earlier APK from <a href="/RBQ/manual/downloads/">Downloads</a> and install it</td></tr><tr><td><strong>Google Play · App Store</strong></td><td><strong>Stores do not offer earlier versions.</strong> If you must roll back, use the direct install above</td></tr></tbody></table><p>The badge on the <code>GUI Version</code> line tells you which build you are on — no badge for a release, <code>NIGHTLY</code> for a nightly, <code>LOCAL</code> for a local build with no release channel. <strong>Only the last 10 days of nightly builds are kept, so you cannot roll back to a nightly older than that</strong> — pick a release version instead.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>Downloading a version needs <strong>internet</strong>; sending it to the robot needs the <strong>robot Wi-Fi</strong>. Download first, then switch networks.</p></div></div><h2 id="offline" tabindex="-1">Rolling back without internet <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Rolling back without internet {#offline}&quot;">​</a></h2><p>On a closed network, roll back from a file.</p><ol><li>Somewhere with internet, download the <code>RBQ-&lt;version&gt;.tar.gz</code> for the version you want and put it on a USB drive.</li><li>On the software update screen press <code>Load from USB or file</code> and pick that file.</li><li>Continue from step 5 of <a href="#rollback-robot">Rolling back the robot</a>.</li></ol><p>The file name must follow <code>RBQ-&lt;version&gt;.tar.gz</code> — the robot refuses anything else.</p><h2 id="after" tabindex="-1">After rolling back <a class="header-anchor" href="#after" aria-label="Permalink to &quot;After rolling back {#after}&quot;">​</a></h2><ul><li>Check that the version on the <code>Current robot</code> card and the <code>GUI Version</code> are the ones you intended.</li><li>Stand the robot up and confirm the <a href="/RBQ/manual/gui/motion-commands.html">basic motions</a> behave normally.</li><li>If there is no camera image, see <a href="/RBQ/manual/troubleshooting/no-camera-view.html">No camera view</a>.</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us the version before, the version you rolled back to, and the symptom that made you roll back.</p><p><strong>→ <a href="/RBQ/manual/support/">Support</a></strong></p>',23)])])}const f=t(l,[["render",i]]);export{g as __pageData,f as default};
